from itertools import combinations


def _route_solver(exact, minimum_duration):
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit_for.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, 0)
        dist = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask, 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if dist.get(state) != time:
                continue
            if (node == data["target"] and mask == full and
                    (not exact or used == data["coupons"])):
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < data["coupons"]:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_used)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, edge["v"], next_mask, next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    def rounded(numerator):
        denominator = 10000
        if data["rounding"] == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    names = sorted(packages, reverse=True)
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best = None

    def cyclic(graph):
        active, done = set(), set()

        def visit(name):
            if name in active:
                return True
            if name in done:
                return False
            active.add(name)
            for other in graph.get(name, ()):
                if visit(other):
                    return True
            active.remove(name)
            done.add(name)
            return False

        return any(visit(name) for name in graph)

    def search(constraints, assigned, graph):
        nonlocal best, best_vector
        pending = [name for name in constraints if name not in assigned]
        if not pending:
            if cyclic(graph):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = dict(assigned)
            return

        name = min(pending)
        ranges = constraints[name]
        rows = [row for row in packages.get(name, [])
                if all(low <= row["version"] <= high for low, high in ranges)
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_constraints = {key: list(value) for key, value in constraints.items()}
            next_graph = {key: list(value) for key, value in graph.items()}
            next_graph.setdefault(name, [])
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                interval = (dep["min"], dep["max"])
                next_constraints.setdefault(target, []).append(interval)
                next_graph[name].append(target)
                if target in next_assigned and not interval[0] <= next_assigned[target] <= interval[1]:
                    valid = False
                    break
            if valid and not cyclic(next_graph):
                search(next_constraints, next_assigned, next_graph)

    initial = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
    search(initial, {}, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    if len(available) < k or not mandatory.issubset({job["id"] for job in available}):
        return {"error": "impossible"}

    for selection in combinations(available, k):
        ids = tuple(sorted(job["id"] for job in selection))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selection:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        valid = True
        for job in sorted(selection, key=lambda item: (item["start"], item["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue

        value = sum(job["value"] for job in selection)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


